def test_stack_preserves_dtype(self) -> None:
    da = xr.DataArray(
        np.zeros((2, 3)),
        dims=("x", "y"),
        coords={
            "x": np.array([10, 20], dtype="int32"),
            "y": np.array([1.5, 2.5, 3.5], dtype="float32"),
        },
    )
    stacked = da.stack(z=("x", "y"))

    assert stacked["x"].values.dtype == np.dtype("int32")
    assert stacked["y"].values.dtype == np.dtype("float32")
    np.testing.assert_array_equal(
        stacked["x"].values,
        np.array([10, 10, 10, 20, 20, 20], dtype="int32"),
    )
    np.testing.assert_array_equal(
        stacked["y"].values,
        np.array([1.5, 2.5, 3.5, 1.5, 2.5, 3.5], dtype="float32"),
    )

